import{_ as c,I as t,o as r,c as l,b6 as i,j as u,J as h,w as d}from"./chunks/framework.BUXTSoD9.js";const v=JSON.parse('{"title":"Thực hành phát triển hệ thống đề xuất phim bằng Spring Boot","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"vi-vn/stage-2/assignments/movie-recommendation-springboot/index.md"}'),o={name:"vi-vn/stage-2/assignments/movie-recommendation-springboot/index.md"},s={style:{margin:"32px 0"}};function g(p,n,m,k,b,x){const a=t("StepBar"),e=t("ClientOnly");return r(),l("div",null,[n[0]||(n[0]=i('<h1 id="thuc-hanh-phat-trien-he-thong-đe-xuat-phim-bang-spring-boot" tabindex="-1">Thực hành phát triển hệ thống đề xuất phim bằng Spring Boot <a class="header-anchor" href="#thuc-hanh-phat-trien-he-thong-đe-xuat-phim-bang-spring-boot" aria-label="Permalink to “Thực hành phát triển hệ thống đề xuất phim bằng Spring Boot”">​</a></h1><h2 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to “Tổng quan”">​</a></h2><p>Dự án thực chiến này yêu cầu bạn hoàn thành một trang web phim có khả năng đề xuất dựa trên một PRD thực tế, sử dụng Spring Boot. Thách thức cốt lõi của dự án này là: nó không phải là thao tác CRUD đơn giản, mà cần bạn suy nghĩ &quot;hành vi người dùng ảnh hưởng đến kết quả đề xuất như thế nào&quot; và &quot;đề xuất có thể giải thích như thế nào&quot;.</p><p>Đây là phần thực hành tổng hợp của Stage 2. Bạn sẽ lần đầu tiên tiếp xúc với mô hình phát triển sản phẩm kiểu &quot;nội dung + hành vi + đề xuất&quot;, mô hình này rất phổ biến trong các kịch bản thương mại điện tử, nền tảng nội dung, Feed cá nhân hóa, v.v.</p><h2 id="kien-thuc-tien-quyet" tabindex="-1">Kiến thức tiên quyết <a class="header-anchor" href="#kien-thuc-tien-quyet" aria-label="Permalink to “Kiến thức tiên quyết”">​</a></h2><p>Trước khi bắt đầu dự án này, bạn nên đã nắm được các nội dung sau:</p><ul><li>Thiết kế trang frontend và sử dụng thư viện component (<a href="./../../frontend/ui-design/">Thiết kế UI</a>, <a href="./../../frontend/modern-component-library/">Thư viện component hiện đại</a>)</li><li>Thiết kế và phát triển API backend (<a href="./../../backend/ai-interface-code/">Viết code API</a>)</li><li>Cơ sở dữ liệu cơ bản và Supabase (<a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a>)</li><li>Quy trình làm việc Git và triển khai (<a href="./../../backend/git-workflow/">Git và GitHub</a>, <a href="./../../backend/zeabur-deployment/">Triển khai ứng dụng Web</a>)</li></ul><h2 id="muc-tieu-hoc-tap" tabindex="-1">Mục tiêu học tập <a class="header-anchor" href="#muc-tieu-hoc-tap" aria-label="Permalink to “Mục tiêu học tập”">​</a></h2><p>Sau khi hoàn thành bài thực hành này, bạn sẽ có thể:</p><ol><li>Đọc PRD và từ đó trích xuất danh sách công việc phát triển hệ thống đề xuất</li><li>Sử dụng Spring Boot để xây dựng dự án backend và triển khai RESTful API</li><li>Thiết kế chuỗi dữ liệu hoàn chỉnh &quot;hành vi người dùng → đề xuất&quot;</li><li>Triển khai logic đề xuất có thể giải thích</li><li>Hoàn thành liên hợp đầu cuối, bàn giao nguyên mẫu sản phẩm có thể demo</li></ol><h2 id="gioi-thieu-du-an" tabindex="-1">Giới thiệu dự án <a class="header-anchor" href="#gioi-thieu-du-an" aria-label="Permalink to “Giới thiệu dự án”">​</a></h2><p>Sản phẩm bạn cần xây dựng là một trang web phim có khả năng đề xuất:</p><table tabindex="0"><thead><tr><th>Chức năng</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Duyệt và tìm kiếm</strong></td><td>Người dùng có thể duyệt và tìm kiếm phim</td></tr><tr><td><strong>Đánh giá và收藏</strong></td><td>Người dùng có thể đánh giá phim, thêm收藏</td></tr><tr><td><strong>Đề xuất cá nhân hóa</strong></td><td>Hệ thống đưa ra kết quả đề xuất dựa trên hành vi người dùng</td></tr><tr><td><strong>Back-office quản trị</strong></td><td>Quản trị viên duy trì dữ liệu phim, xem hiệu quả đề xuất</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Đường dẫn PRD</p><p>Tài liệu yêu cầu của dự án này nằm trên GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">Xem PRD</a></p></div>',14)),u("div",s,[h(e,null,{default:d(()=>[h(a,{active:0,items:[{title:"Phân tích yêu cầu",description:"Đọc PRD, xác định chiến lược đề xuất, dữ liệu hành vi và phạm vi back-office"},{title:"Xây dựng khung",description:"Dùng AI tạo trang danh sách, trang chi tiết, trang đề xuất và trang back-office"},{title:"Phát triển lặp",description:"Bổ sung logic đề xuất, ghi hành vi và quản lý back-office"},{title:"Liên hợp & triển khai",description:"Chạy đầu cuối, triển khai và chuẩn bị demo"}]})]),_:1})]),n[1]||(n[1]=i(`<h2 id="phan-1-phan-tich-yeu-cau" tabindex="-1">Phần 1: Phân tích yêu cầu <a class="header-anchor" href="#phan-1-phan-tich-yeu-cau" aria-label="Permalink to “Phần 1: Phân tích yêu cầu”">​</a></h2><h3 id="_1-1-đoc-prd" tabindex="-1">1.1 Đọc PRD <a class="header-anchor" href="#_1-1-đoc-prd" aria-label="Permalink to “1.1 Đọc PRD”">​</a></h3><p>Mở tài liệu PRD, tập trung trả lời các câu hỏi sau:</p><ul><li>Chiến lược đề xuất là gì? Phiên bản đầu tiên có sử dụng phiên bản có thể giải thích (như dựa trên độ tương tự đánh giá) không?</li><li>Dữ liệu hành vi người dùng cần lưu những gì? (Đánh giá,收藏, bản ghi duyệt, v.v.)</li><li>Quản trị viên cần xem những chỉ số hiệu quả đề xuất nào?</li><li>Danh sách trang đã hoàn chỉnh chưa?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Nếu các câu hỏi trên chưa có câu trả lời rõ ràng, đừng bắt đầu viết code. Hiểu sai yêu cầu là nguyên nhân phổ biến nhất dẫn đến phải làm lại.</p></div><h3 id="_1-2-xac-nhan-kien-truc-he-thong" tabindex="-1">1.2 Xác nhận kiến trúc hệ thống <a class="header-anchor" href="#_1-2-xac-nhan-kien-truc-he-thong" aria-label="Permalink to “1.2 Xác nhận kiến trúc hệ thống”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Trang frontend&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; auth[&quot;Xác thực người dùng&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; movie[&quot;Danh sách / Chi tiết phim&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; behavior[&quot;Đánh giá / 收藏&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  behavior --&gt; reco[&quot;Logic đề xuất&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reco --&gt; db[&quot;Cơ sở dữ liệu&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin[&quot;Back-office quản trị&quot;] --&gt; db</span></span></code></pre></div><h2 id="phan-2-xay-dung-khung-du-an" tabindex="-1">Phần 2: Xây dựng khung dự án <a class="header-anchor" href="#phan-2-xay-dung-khung-du-an" aria-label="Permalink to “Phần 2: Xây dựng khung dự án”">​</a></h2><h3 id="_2-1-tao-trang-frontend" tabindex="-1">2.1 Tạo trang frontend <a class="header-anchor" href="#_2-1-tao-trang-frontend" aria-label="Permalink to “2.1 Tạo trang frontend”">​</a></h3><p>Tham khảo prompt:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vui lòng dựa trên PRD hiện tại, giúp tôi tạo khung frontend của hệ thống đề xuất phim bằng Spring Boot.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Yêu cầu:</span></span>
<span class="line"><span>1. Trang bao gồm: trang chủ, danh sách phim, chi tiết phim, trang đề xuất, trang cá nhân, back-office quản trị</span></span>
<span class="line"><span>2. Trước tiên chỉ tạo cấu trúc trang và dữ liệu giả, không kết nối API thực tế</span></span>
<span class="line"><span>3. Phong cách phải giống sản phẩm nội dung thực tế, chứ không phải demo lớp học</span></span></code></pre></div><h3 id="_2-2-xac-minh-cau-truc-trang" tabindex="-1">2.2 Xác minh cấu trúc trang <a class="header-anchor" href="#_2-2-xac-minh-cau-truc-trang" aria-label="Permalink to “2.2 Xác minh cấu trúc trang”">​</a></h3><p>Kiểm tra từng mục:</p><ul><li>[ ] Trang danh sách phim hỗ trợ tìm kiếm và lọc</li><li>[ ] Trang chi tiết phim bao gồm nút đánh giá và收藏</li><li>[ ] Trang đề xuất có thể hiển thị kết quả đề xuất và lý do đề xuất</li><li>[ ] Back-office quản trị có thể hiển thị dữ liệu phim và hiệu quả đề xuất</li></ul><h2 id="phan-3-phat-trien-lap" tabindex="-1">Phần 3: Phát triển lặp <a class="header-anchor" href="#phan-3-phat-trien-lap" aria-label="Permalink to “Phần 3: Phát triển lặp”">​</a></h2><h3 id="_3-1-trien-khai-theo-module" tabindex="-1">3.1 Triển khai theo module <a class="header-anchor" href="#_3-1-trien-khai-theo-module" aria-label="Permalink to “3.1 Triển khai theo module”">​</a></h3><ol><li><strong>Xây dựng dự án Spring Boot</strong>: Cấu trúc dự án, cấu hình cơ sở dữ liệu, CRUD cơ bản</li><li><strong>Quản lý dữ liệu phim</strong>: Danh sách phim, chi tiết, API tìm kiếm</li><li><strong>Hành vi người dùng</strong>: API đánh giá,收藏, ghi dữ liệu hành vi</li><li><strong>Logic đề xuất</strong>: Triển khai thuật toán đề xuất dựa trên hành vi người dùng</li><li><strong>Hiển thị đề xuất</strong>: Hiển thị kết quả đề xuất, bao gồm lý do đề xuất</li><li><strong>Back-office quản trị</strong>: Duy trì dữ liệu phim, xem hiệu quả đề xuất</li></ol><h3 id="_3-2-tu-kiem-tra-module" tabindex="-1">3.2 Tự kiểm tra module <a class="header-anchor" href="#_3-2-tu-kiem-tra-module" aria-label="Permalink to “3.2 Tự kiểm tra module”">​</a></h3><table tabindex="0"><thead><tr><th>Mục kiểm tra</th><th>Phương pháp xác minh</th></tr></thead><tbody><tr><td>Chức năng cơ bản</td><td>Danh sách, chi tiết, đánh giá,收藏 có thành chuỗi hoàn chỉnh không</td></tr><tr><td>Liên kết đề xuất</td><td>Hành vi người dùng có ảnh hưởng đến kết quả đề xuất không</td></tr><tr><td>Tính có thể giải thích của đề xuất</td><td>Người dùng có thể hiểu tại sao được đề xuất những phim này không</td></tr><tr><td>Dữ liệu back-office</td><td>Quản trị viên có thể xem dữ liệu phim và hiệu quả đề xuất không</td></tr></tbody></table><h2 id="phan-4-lien-hop-va-trien-khai" tabindex="-1">Phần 4: Liên hợp và Triển khai <a class="header-anchor" href="#phan-4-lien-hop-va-trien-khai" aria-label="Permalink to “Phần 4: Liên hợp và Triển khai”">​</a></h2><h3 id="_4-1-kiem-thu-đau-cuoi" tabindex="-1">4.1 Kiểm thử đầu cuối <a class="header-anchor" href="#_4-1-kiem-thu-đau-cuoi" aria-label="Permalink to “4.1 Kiểm thử đầu cuối”">​</a></h3><p>Ít nhất xác minh các kịch bản sau:</p><ul><li>Duyệt phim → Đánh giá →收藏 → Xem trang đề xuất, xác nhận kết quả đề xuất thay đổi</li><li>Quản trị viên đăng nhập → Thêm phim → Xem thống kê hiệu quả đề xuất</li></ul><h2 id="san-pham-ban-giao" tabindex="-1">Sản phẩm bàn giao <a class="header-anchor" href="#san-pham-ban-giao" aria-label="Permalink to “Sản phẩm bàn giao”">​</a></h2><p>Sau khi hoàn thành dự án này, bạn cần nộp các nội dung sau:</p><ul><li>[ ] Liên kết demo trực tuyến có thể truy cập</li><li>[ ] Liên kết kho mã nguồn (bao gồm README)</li><li>[ ] Tài liệu PRD</li><li>[ ] Ảnh chụp màn hình các trang cốt lõi (danh sách phim, chi tiết phim, trang đề xuất, back-office quản trị)</li><li>[ ] Video demo 60 giây</li></ul><h2 id="tieu-chi-cham-điem" tabindex="-1">Tiêu chí chấm điểm <a class="header-anchor" href="#tieu-chi-cham-điem" aria-label="Permalink to “Tiêu chí chấm điểm”">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Yêu cầu cơ bản</th><th>Yêu cầu nâng cao</th></tr></thead><tbody><tr><td>Căn chỉnh PRD</td><td>Trang, chức năng, cấu trúc dữ liệu cơ bản khớp với PRD</td><td>Có thể giải thích rõ ràng quyết định thiết kế</td></tr><tr><td>Chuỗi sản phẩm</td><td>Duyệt → Đánh giá →收藏 → Đề xuất có thể chạy qua</td><td>Hành vi đánh giá rõ ràng ảnh hưởng đến kết quả đề xuất</td></tr><tr><td>Chất lượng đề xuất</td><td>Kết quả đề xuất hợp lý, lý do đề xuất có thể giải thích</td><td>Hỗ trợ nhiều chiến lược đề xuất</td></tr><tr><td>Khả năng back-office</td><td>Dữ liệu phim và hiệu quả đề xuất có thể xem</td><td>Có chỉ số thống kê như độ chính xác đề xuất</td></tr><tr><td>Độ hoàn thiện kỹ thuật</td><td>Frontend, backend Spring Boot, chuỗi cơ sở dữ liệu đã kết nối</td><td>API đề xuất có bộ nhớ đệm hoặc tối ưu hiệu suất</td></tr></tbody></table><h2 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Thiết kế UI</a></li><li><a href="./../../frontend/modern-component-library/">Sử dụng thư viện component hiện đại để cập nhật giao diện</a></li><li><a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Mô hình hỗ trợ viết code API và tài liệu API bằng mô hình lớn</a></li><li><a href="./../../backend/git-workflow/">Quy trình làm việc Git và GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Cách triển khai ứng dụng Web</a></li></ul>`,30))])}const y=c(o,[["render",g]]);export{v as __pageData,y as default};
